mapper.select:
select mdi.DEALER_NO, mci.CUSTOMER_ABBR dealerName, MDDI.DEALER_PARTY_NO, MDDI.DEALER_PARTY_TYPE, MDDI.DEALER_PARTY_NAME, MDDI.TRADER_NO , MDDI.TRADER_NAME , MDDI.IS_OUR from MST_DEALER_INFO mdi LEFT JOIN MST_DEALER_DETAIL_INFO MDDI on mdi.DEALER_NO = MDDI.DEALER_NO and MDDI.CUSTOMER_ID=mdi.CUSTOMER_ID left join MST_CUSTOMER_INFO mci on mci.CUSTOMER_ID = mdi.CUSTOMER_ID left join MST_SALE_DEPARTMENT MSD on MDDI.CUSTOMER_ID =MSD.BROKER_ID LEFT JOIN STL_CAPACCT_INFO SCI ON MSD.SALE_DEPID = SCI.OWN_DEPT left join STL_SEC_ACCT_INFO SSAI on SCI.ACCT_NO = SSAI.TRD_ACCT_ID
SSAI.TRADE_PLACE = #{tradePlace}
and SSAI.TRD_ACCT_ID = #{acctNo}
and MDDI.IS_OUR = #{isOur}
and mdi.DEALER_NO = #{dealerNo}
and mci.CUSTOMER_ABBR like concat(concat('%',#{dealerName}),'%')
and MDDI.TRADER_NO like concat(concat('%',#{traderNo}),'%')
and MDDI.TRADER_NAME like concat(concat('%',#{traderName}),'%')
and MDDI.DEALER_PARTY_NO like concat(concat('%',#{dealerPartyNo}),'%')
and MDDI.DEALER_PARTY_NAME like concat(concat('%',#{dealerPartyName}),'%')

mapper.delete:
delete from  MST_DEALER_DETAIL_INFO mddi

    mddi.CUSTOMER_ID = #{customerId,jdbcType="VARCHAR"}
    and mddi.DEALER_PARTY_NO =#{dealerPartyNo,jdbcType="VARCHAR"}
    and mddi.TRADER_NO = #{traderNo,jdbcType="VARCHAR"}

delete from MST_DEALER_INFO
where CUSTOMER_ID = #{customerId}
and DEALER_NO = #{dealerNo}
